const csv = $input.first().json.data || $input.first().binary?.data;
const text = items[0].json.data || items[0].json.body || items[0].json;
const raw = typeof text === 'string' ? text : items[0].json.toString();

function parseCSV(str) {
  const lines = str.trim().split('
');
  const headers = lines[0].split(',').map(h => h.trim());
  return lines.slice(1).map(line => {
    const vals = line.split(',');
    const obj = {};
    headers.forEach((h, i) => obj[h] = vals[i] ? vals[i].trim() : '');
    return obj;
  });
}

const rows = parseCSV(raw);

const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const yStr = yesterday.toISOString().slice(0,10);

const todaysOrders = rows.filter(r => r.order_date === yStr);
const dataset = todaysOrders.length > 0 ? todaysOrders : rows;

const total = dataset.length;
const cancelled = dataset.filter(r => r.order_status === 'Cancelled').length;
const cancellation_rate = total > 0 ? cancelled / total : 0;

const delTimes = dataset
  .map(r => parseFloat(r.delivery_time_mins))
  .filter(v => !isNaN(v));
const avg_delivery_time = delTimes.length > 0
  ? delTimes.reduce((a,b) => a+b, 0) / delTimes.length
  : 0;

const zoneComplaints = {};
dataset.forEach(r => {
  const z = r.delivery_zone;
  const c = parseInt(r.customer_complaints) || 0;
  zoneComplaints[z] = (zoneComplaints[z] || 0) + c;
});
const worst_zone = Object.entries(zoneComplaints)
  .sort((a,b) => b[1]-a[1])[0]?.[0] || 'N/A';

const restCancel = {};
dataset.forEach(r => {
  if (r.order_status === 'Cancelled') {
    restCancel[r.restaurant_name] = (restCancel[r.restaurant_name] || 0) + 1;
  }
});
const worst_restaurant = Object.entries(restCancel)
  .sort((a,b) => b[1]-a[1])[0]?.[0] || 'N/A';

const highRiskRows = dataset.filter(r => r.cancel_risk === 'high' || r.cancel_risk === 'True' || r.cancel_risk === 'true');
const riskPairs = {};
highRiskRows.forEach(r => {
  const key = `${r.restaurant_name} - ${r.delivery_zone}`;
  riskPairs[key] = (riskPairs[key] || 0) + 1;
});
const top_risk_pair = Object.entries(riskPairs)
  .sort((a,b) => b[1]-a[1])[0]?.[0] || 'N/A';

const today = new Date().toISOString().slice(0,10);

return [{
  json: {
    total_orders: total,
    cancellation_rate: cancellation_rate,
    avg_delivery_time: Math.round(avg_delivery_time * 10) / 10,
    worst_zone: worst_zone,
    worst_restaurant: worst_restaurant,
    top_risk_pair: top_risk_pair,
    date: today
  }
}];

